import type { MetadataRoute } from "next";

// The install manifest (served at /manifest.webmanifest, public: the proxy
// skips .webmanifest). Colours are --bg-base (#0E1116): the manifest can't
// read CSS variables. Icons are generated by scripts/icons/generate.mjs.
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "Donquixote FX",
    short_name: "Donquixote",
    description: "DG's forex setups, caught for him.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#0E1116",
    theme_color: "#0E1116",
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
